import {createWorkflow,filterWorkflows,moveStep,progressPercent} from './model.js';
const seed=[{id:'payroll',title:'Run biweekly payroll',category:'Finance',status:'Published',views:148,completions:102,updated:'2 days ago',steps:[{id:'p1',title:'Open the payroll workspace',description:'Sign in and choose the current pay period.'},{id:'p2',title:'Review time entries',description:'Resolve flagged or incomplete timesheets.'},{id:'p3',title:'Approve and submit',description:'Confirm totals, then schedule the payroll run.'}]},{id:'onboard',title:'Welcome a new teammate',category:'People',status:'Published',views:93,completions:71,updated:'5 days ago',steps:[{id:'o1',title:'Create their profile',description:'Add the teammate to your people directory.'},{id:'o2',title:'Assign essentials',description:'Share the first-week checklist and key tools.'}]},{id:'refund',title:'Process a customer refund',category:'Support',status:'Draft',views:21,completions:8,updated:'Today',steps:[{id:'r1',title:'Find the order',description:'Search by order number or customer email.'},{id:'r2',title:'Confirm eligibility',description:'Check the purchase date and refund policy.'}]}];
const stored=localStorage.getItem('pathira-workflows')||localStorage.getItem('learnsify-workflows');let workflows=stored?JSON.parse(stored):seed;let view='library',active=null,query='',category='All',status='All',guideIndex=0,captureActive=false,captureCount=0;
const app=document.querySelector('#app');const save=()=>localStorage.setItem('pathira-workflows',JSON.stringify(workflows));
function shell(content){return `<div class="shell"><aside class="side" id="sidebar"><a class="brand" href="index.html"><img class="brand-logo" src="assets/apple-touch-icon.png" alt="Pathira logo">Pathira</a><div class="workspace"><small>Workspace</small><div>Learning Lab ▾</div></div><nav class="nav"><a class="nav-button active" id="nav-guides" href="index.html">▦ &nbsp; Guides</a><button id="nav-analytics">◫ &nbsp; Analytics</button><button id="nav-team">♧ &nbsp; Team</button></nav><div class="side-foot">Make work teachable.<br><br>JR<br>Workspace owner</div></aside><main class="main"><div class="top"><button class="btn mobile-menu" id="mobile-menu" aria-label="Toggle navigation">☰</button><span class="eyebrow">Pathira workspace</span><button class="btn" id="invite">Invite team</button></div>${content}</main></div>`}
function render(){if(view==='editor')return renderEditor();const visible=filterWorkflows(workflows,query,category,status),views=workflows.reduce((a,x)=>a+x.views,0),done=workflows.reduce((a,x)=>a+x.completions,0);app.innerHTML=shell(`<section class="hero"><div><p class="eyebrow">Knowledge that moves with your team</p><h1>Turn “show me” into something people can follow.</h1><p class="sub">Capture repeatable work, shape it into a clear guide, and let your team learn at their own pace.</p></div><a class="btn primary" id="new" href="create.html">＋ Create guide</a></section><section class="stats"><div class="stat"><strong>${workflows.length}</strong><span>Guides in your library</span></div><div class="stat"><strong>${views}</strong><span>Total guide views</span></div><div class="stat"><strong>${views?Math.round(done/views*100):0}%</strong><span>Average completion</span></div></section><div class="filters"><div class="search"><input id="search" value="${query}" placeholder="Search your guides…"></div><select id="category"><option>All</option>${['Finance','People','Support','Operations'].map(x=>`<option ${x===category?'selected':''}>${x}</option>`).join('')}</select><select id="status"><option>All</option>${['Published','Draft'].map(x=>`<option ${x===status?'selected':''}>${x}</option>`).join('')}</select></div><section class="grid">${visible.map(card).join('')||'<div class="empty">No guides match those filters.</div>'}</section>`);bindLibrary();bindShellControls()}
function card(w){return `<article class="card" data-id="${w.id}"><div class="thumb"><span class="chip">${w.category}</span></div><div class="card-body"><span class="badge">${w.status}</span><h3>${w.title}</h3><div class="meta"><span>${w.steps.length} steps · ${w.views} views</span><span>${w.updated}</span></div></div></article>`}
function bindLibrary(){document.querySelector('#search').oninput=e=>{query=e.target.value;render()};document.querySelector('#category').onchange=e=>{category=e.target.value;render()};document.querySelector('#status').onchange=e=>{status=e.target.value;render()};document.querySelectorAll('.card').forEach(x=>x.onclick=()=>{active=workflows.find(w=>w.id===x.dataset.id);view='editor';render()})}
function renderEditor(){const w=active;app.innerHTML=shell(`<button class="back" id="back">← Back to guides</button><div class="editor-head"><div><span class="eyebrow">${w.category} · ${w.status}</span><input class="title-input" id="title" value="${w.title}"><p class="sub">Build a focused path your learner can finish with confidence.</p></div><div class="guide-actions"><button class="btn" id="share">Share</button><button class="btn primary" id="preview">▶ Guide view</button></div></div><div class="editor"><section class="panel"><div class="step-head"><h2>${w.steps.length} learning steps</h2><button class="btn ${captureActive?'primary':'dark'}" data-pathira-control id="capture">${captureActive?`■ Stop capture (${captureCount})`:'● Capture browser'}</button></div>${captureActive?'<p class="capture-note">Recording across browser tabs. Return here and press Stop capture when finished.</p>':''}<div id="steps">${w.steps.map((s,i)=>step(s,i,w.steps.length)).join('')}</div><button class="btn" id="add">＋ Add step</button></section><aside class="panel sidepanel"><h3>Guide health</h3><div class="metric"><strong>${w.views}</strong><span>Views</span></div><div class="metric"><strong>${w.completions}</strong><span>Completions</span></div><div class="metric"><strong>${w.views?Math.round(w.completions/w.views*100):0}%</strong><span>Completion rate</span></div></aside></div>`);bindEditor();bindShellControls()}
function step(s,i,total){return `<article class="step" data-i="${i}"><div class="step-head"><span class="num">${i+1}</span><div class="step-tools"><button class="up" ${i===0?'disabled':''}>↑</button><button class="down" ${i===total-1?'disabled':''}>↓</button><button class="delete">×</button></div></div>${s.screenshot?`<img class="step-screenshot" src="${s.screenshot}" alt="Captured screen for step ${i+1}">`:''}<input class="step-title" value="${s.title}"><textarea class="step-desc">${s.description}</textarea>${s.url?`<a class="step-url" href="${s.url}" target="_blank" rel="noopener">${s.pageTitle||'Open captured page'} ↗</a>`:''}</article>`}
function bindEditor(){document.querySelector('#back').onclick=()=>{view='library';render()};document.querySelector('#title').onchange=e=>{active.title=e.target.value;save()};document.querySelector('#add').onclick=()=>{active.steps.push({id:crypto.randomUUID(),title:'New step',description:'Describe what the learner should do and why.'});save();render()};document.querySelector('#capture').onclick=toggleBrowserCapture;document.querySelector('#share').onclick=showShare;document.querySelector('#preview').onclick=showGuide;document.querySelectorAll('.step').forEach(el=>{const i=+el.dataset.i;el.querySelector('.up').onclick=()=>{active.steps=moveStep(active.steps,i,-1);save();render()};el.querySelector('.down').onclick=()=>{active.steps=moveStep(active.steps,i,1);save();render()};el.querySelector('.delete').onclick=()=>{active.steps.splice(i,1);save();render()};el.querySelector('.step-title').onchange=e=>{active.steps[i].title=e.target.value;save()};el.querySelector('.step-desc').onchange=e=>{active.steps[i].description=e.target.value;save()}})}
function bindShellControls(){document.querySelector('#nav-analytics').onclick=showAnalytics;document.querySelector('#nav-team').onclick=showInvite;document.querySelector('#invite').onclick=showInvite;document.querySelector('#mobile-menu').onclick=toggleMobileMenu}
function toggleMobileMenu(){document.querySelector('#sidebar').classList.toggle('open')}
function showAnalytics(){const views=workflows.reduce((sum,w)=>sum+w.views,0),done=workflows.reduce((sum,w)=>sum+w.completions,0);document.body.insertAdjacentHTML('beforeend',`<div class="overlay" id="overlay"><div class="modal"><div class="modal-head"><h2>Workspace analytics</h2><button class="btn icon" id="close">×</button></div><div class="stats modal-stats"><div class="stat"><strong>${workflows.length}</strong><span>Guides</span></div><div class="stat"><strong>${views}</strong><span>Views</span></div><div class="stat"><strong>${views?Math.round(done/views*100):0}%</strong><span>Completion</span></div></div></div></div>`);document.querySelector('#close').onclick=()=>document.querySelector('#overlay').remove()}
function showInvite(){document.body.insertAdjacentHTML('beforeend',`<div class="overlay" id="overlay"><form class="modal" id="invite-form"><div class="modal-head"><h2>Invite a teammate</h2><button type="button" class="btn icon" id="close">×</button></div><p class="sub">Send an invitation to collaborate in your Pathira workspace.</p><label>Email address</label><input class="field" id="invite-email" type="email" required placeholder="teammate@company.com"><div class="modal-actions"><button type="button" class="btn" id="cancel">Cancel</button><button class="btn primary">Send invite</button></div></form></div>`);document.querySelector('#close').onclick=document.querySelector('#cancel').onclick=()=>document.querySelector('#overlay').remove();document.querySelector('#invite-form').onsubmit=e=>{e.preventDefault();const email=document.querySelector('#invite-email').value;document.querySelector('#overlay').remove();toast(`Invitation prepared for ${email}`)}}
function showShare(){const url=`${location.origin}${location.pathname}#guide/${active.id}`;document.body.insertAdjacentHTML('beforeend',`<div class="overlay" id="overlay"><div class="modal"><div class="modal-head"><h2>Share this guide</h2><button class="btn icon" id="close">×</button></div><p class="sub">Anyone with this demo link can open the guide.</p><input class="field" id="link" readonly value="${url}"><div class="modal-actions"><button class="btn primary" id="copy">Copy link</button></div></div></div>`);const overlay=document.querySelector('#overlay');overlay.querySelector('#close').onclick=()=>overlay.remove();overlay.querySelector('#copy').onclick=async()=>{await navigator.clipboard.writeText(overlay.querySelector('#link').value);toast('Link copied')}}
function showGuide(){guideIndex=0;drawGuide()}
function drawGuide(){document.querySelector('#overlay')?.remove();const s=active.steps[guideIndex];if(!s)return toast('Add a step first');const pct=progressPercent(guideIndex,active.steps.length);const media=s.screenshot?`<img src="${s.screenshot}" alt="Captured screen for ${s.title}">`:`<div class="mock-window"><strong>Interactive workspace</strong><div class="mock-line"></div><div class="mock-line" style="width:72%"></div><div class="mock-line" style="width:45%;background:#ff654d"></div></div>`;document.body.insertAdjacentHTML('beforeend',`<div class="overlay" id="overlay"><div class="modal guide"><div class="guide-media">${media}</div><div class="guide-copy"><div class="modal-head"><span class="eyebrow">Step ${guideIndex+1} of ${active.steps.length}</span><button class="btn icon" id="close">×</button></div><div class="progress"><i style="width:${pct}%"></i></div><h2>${s.title}</h2><p class="sub">${s.description}</p><div class="guide-actions"><button class="btn" id="prev" ${guideIndex===0?'disabled':''}>Back</button><button class="btn primary" id="next">${guideIndex===active.steps.length-1?'Finish':'Next step'}</button></div></div></div></div>`);const overlay=document.querySelector('#overlay');overlay.querySelector('#close').onclick=()=>overlay.remove();overlay.querySelector('#prev').onclick=()=>{guideIndex--;drawGuide()};overlay.querySelector('#next').onclick=()=>{if(guideIndex<active.steps.length-1){guideIndex++;drawGuide()}else{active.views++;active.completions++;save();overlay.remove();toast('Guide completed')}}}
function toast(msg){document.querySelector('.toast')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="toast">${msg}</div>`);setTimeout(()=>document.querySelector('.toast')?.remove(),1800)}
function toggleBrowserCapture(){
  const type=captureActive?'PATHIRA_STOP_CAPTURE':'PATHIRA_START_CAPTURE';
  let answered=false;
  window.postMessage({type},'*');
  setTimeout(()=>{if(!answered&&!captureActive)showExtensionHelp()},900);
  const once=event=>{if(!['PATHIRA_CAPTURE_STATUS','PATHIRA_CAPTURE_RESULT'].includes(event.data?.type))return;answered=true;window.removeEventListener('message',once)};
  window.addEventListener('message',once);
}
function showExtensionHelp(){if(document.querySelector('#overlay'))return;document.body.insertAdjacentHTML('beforeend',`<div class="overlay" id="overlay"><div class="modal"><div class="modal-head"><h2>Install Pathira Capture</h2><button class="btn icon" id="close">×</button></div><p class="sub">Chrome needs the Pathira extension to record clicks across tabs.</p><ol><li>Download or clone the GitHub repository.</li><li>Open <strong>chrome://extensions</strong> and enable Developer mode.</li><li>Choose <strong>Load unpacked</strong> and select the <strong>extension</strong> folder.</li><li>Refresh Pathira and start capturing.</li></ol><div class="modal-actions"><a class="btn primary" href="https://github.com/jrosecode/Pathira" target="_blank">Get extension</a></div></div></div>`);const overlay=document.querySelector('#overlay');overlay.querySelector('#close').onclick=()=>overlay.remove()}
window.addEventListener('message',event=>{
  if(event.source!==window)return;
  if(event.data?.type==='PATHIRA_CAPTURE_STATUS'){captureActive=!!event.data.active;captureCount=event.data.count||0;if(view==='editor')render()}
  if(event.data?.type==='PATHIRA_CAPTURE_RESULT'){captureActive=false;captureCount=0;const steps=event.data.steps||[];if(steps.length){active.steps.push(...steps);save();toast(`${steps.length} captured step${steps.length===1?'':'s'} added`)}else toast('No clicks were captured');if(view==='editor')render()}
});
window.postMessage({type:'PATHIRA_STATUS_REQUEST'},'*');
const hashId=location.hash.match(/^#guide\/(.+)$/)?.[1];if(hashId){active=workflows.find(x=>x.id===hashId);if(active){view='editor';render();showGuide()}else render()}else render();
